def exact(actual, expected, label):
    if json.dumps(actual, sort_keys=True, default=lambda b: ["bytes", b.hex()]) != json.dumps(expected, sort_keys=True, default=lambda b: ["bytes", b.hex()]):
        raise ValueError(label)

def sha(content):
    return hashlib.sha256(content).hexdigest()

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or rel.startswith('/') or any(x in ('', '.', '..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p = root / safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute() != p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('unsafe file ' + rel)
    return p.read_bytes()

def validate_confirmation(c,receipt):
    exact(sha((json.dumps(c,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),CONFIRMATION_SHA256,'external327 confirmation')
    exact(sorted(receipt),['encoding','original_display_sha256','original_display_size_bytes','text'],'receipt fields')
    exact(receipt['encoding'],'utf8-json-text','receipt encoding'); raw=receipt['text'].encode()
    exact(sha(raw),RECEIPT_SHA256,'original327 digest'); exact(len(raw),114960,'original327 length')
    exact(receipt['original_display_sha256'],RECEIPT_SHA256,'receipt metadata digest'); exact(receipt['original_display_size_bytes'],114960,'receipt metadata size')
    lines=receipt['text'].splitlines(); exact(sum(x.startswith('PASS: ') for x in lines),1361,'complete1361 return')
    exact(lines.count('Result: PASS (1361 passes, 0 failures)'),1,'full1361 summary')
    log='e49029b (HEAD -> main, origin/main, origin/HEAD) Phase 1 step 327: review scoped effects obligations and rights crossclosure'
    exact(lines.count(log),2,'matching327 HEAD origin')
    if '[main e49029b]' not in receipt['text'] or 'aae7c8b..e49029b  main -> main' not in receipt['text']: raise ValueError('missing327 commit/push')
    return True

def verify_history(root, policy):
    binding = policy['baseline_sha256_bindings']
    serialized = (json.dumps(binding, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()
    exact(sha(serialized),BASELINE_JSON_SHA256,'exact accepted1530 manifest')
    exact(len(binding),1530,'accepted1530 file count')
    history = {}
    for rel,digest in binding.items():
        content = safe_file(root,rel)
        if rel == 'CHANGELOG.md':
            prefix = CHANGELOG_PREFIX.encode()
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            exact(content[:len(prefix)],prefix,'new CHANGELOG prefix')
            content = content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel] = content
    return history

def validate_freeze(freeze,prior,frozen,history):
    exact(freeze,FREEZE_SPEC,'exact scoped integration design freeze')
    exact(sha((json.dumps(prior,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),PRIOR_DESIGN_SHA256,'exact327 crossclosure')
    for step,binding in freeze['successor_contract_bindings'].items():
        raw=history[binding['path']]; exact(sha(raw),binding['sha256'],'exact successor design '+step)
        source=json.loads(raw)
        exact(freeze['frozen_contract_views'][step],{key:source[key] for key in freeze['contract_view_fields'][step]},'selected normative view '+step)
    plan=freeze['original_resume_plan_binding']; exact(sha(history[plan['path']]),plan['sha256'],'exact319 original plan')
    original=json.loads(history[plan['path']]); exact(original['preferred_step_range'],[319,328],'original ten-step route')
    exact(original['pause_scope'],freeze['pause_contract']['scope'],'unchanged scoped pause selection')
    exact(original['pause_conditions'],freeze['pause_contract']['original_pause_conditions'],'original pause conditions')
    exact(freeze['seven_requirements_bindings'],frozen['seven_review_bindings'],'seven frozen capabilities')
    exact(freeze['preserved_cross_obligations'],frozen['proof_obligations'],'ten frozen obligations')
    for binding in freeze['seven_requirements_bindings']:
        for role in ['policy','review']: exact(sha(history[binding[role+'_path']]),binding[role+'_sha256'],'capability source '+binding['capability']+'/'+role)
    for proof in freeze['future_proof_register']:
        source=json.loads(history[proof['source_design_path']]); index={r['id']:r for r in source['future_proof_obligations']}
        exact(proof['source_proof'],index[proof['source_proof']['id']],'exact retained proof '+proof['qualified_id'])
        exact(proof['source_design_sha256'],sha(history[proof['source_design_path']]),'proof source SHA')
    exact([row['step'] for row in freeze['batch_acceptance_register']],list(range(319,329)),'complete319-328 route')
    for row in freeze['batch_acceptance_register'][:-1]:
        if row['step']==327:
            exact(row['source_confirmation_sha256'],CONFIRMATION_SHA256,'current327 external confirmation SHA')
