def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode('ascii')

def unique_pairs(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON field')
        result[key]=value
    return result


def evaluate_private_pause(value):
    exact(sorted(value),['acceptance','claim_scope','conditions','effects','host_state','origin','scope'],'pause fields')
    exact(value['origin'],'synthetic-private-fixture','pause origin')
    exact(value['scope'],'conditional-repository-pause-contract-only','pause model scope')
    exact(value['host_state'],'unobserved-not-claimed-absent','actual host outside delivery remains unobserved')
    if type(value['claim_scope']) is not str or value['claim_scope'] not in [PAUSE_SCOPE,'actual-global-host-closure','actual-runtime-readiness']: raise ValueError('typed pause claim scope')
    for domain,keys in [('conditions',PAUSE_GATES),('acceptance',ACCEPTANCE_KEYS),('effects',BATCH_EFFECT_KEYS)]:
        if type(value[domain]) is not dict: raise ValueError('typed pause domain '+domain)
        exact(sorted(value[domain]),sorted(keys),'complete pause domain '+domain)
